const MinigameDef MINIGAMES[] = {
  {"stretch-snatch", "Stretch & Snatch", "Reach across the spinning feast!", "A feast table spins on a pirate ship’s deck. Aim your rubbery arm, hold A to stretch it across the table and let go to snap back with whatever you grabbed. Golden roasts are worth the most — but crossed arms tangle, the cook’s rolling pin bonks and the gulls steal!", {"Aim with the stick, hold A to stretch — let go to snap back with your grab", "Fruit 1, drumsticks 2, golden roasts 5 — up to 3 in one reach", "Crossed arms tangle and drop it all; dodge the cook’s rolling pin", "Most food after 45 seconds wins"}, "pirates", 0xe5484d, "mg/arena_stretch-snatch.png", false},
  {"triple-slash", "Triple Slash", "Three lanes, three blades — slice on the beat!", "Barrels, crates and flying fish hurtle down the cargo chutes toward you. Slice each one as it crosses the line in its lane — right on the beat for a PERFECT — and build a combo. Let the fizzing bombs roll past!", {"X slices the left lane, A the centre, B the right (or the D-pad)", "Slice as each one crosses the line — on the beat is PERFECT", "Keep slicing for a combo; a miss or a wild swing breaks it", "Let bombs roll past! Top score after 40 seconds wins"}, "pirates", 0x3f9e5a, "mg/arena_triple-slash.png", false},
  {"storm-navigator", "Storm Navigator", "Read the wind, ride the storm!", "Sail your dinghy round a stormy bay scooping up floating treasure. Watch the weather vane: sailing straight into the wind stalls you, so steer across it. Dodge the lightning strikes and keep clear of the roaming whirlpool!", {"Steer with the stick — sailing into the wind stalls you", "Watch the vane: sail across or with the wind to go fast", "A pumps the sail for a burst; ram a rival to knock treasure loose", "Dodge lightning and the whirlpool — most treasure in 50 s wins"}, "pirates", 0x2f7fb5, "mg/arena_storm-navigator.png", false},
  {"cloud-rider", "Cloud Rider", "Surf the golden clouds between the peaks!", "Ride a little golden cloud through a sky course between the mountain peaks. Fly through rings, grab glowing energy orbs and burst ahead to bump rivals off their line, but steer clear of storm clouds and wind gusts!", {"Steer through rings (+1) and energy orbs (+3)", "Hold A to charge, let go to burst ahead", "Ram rivals for rings; dodge storms and wind", "Most rings after 45 seconds wins"}, "dojo", 0xf5a524, "mg/arena_cloud-rider.png", false},
  {"clone-chaos", "Clone Chaos", "Which one is the real ninja?", "A ninja hides among a crowd of identical smoke clones that leap and shuffle across the village rooftops. Keep your eyes on the real one and lock in your pick before the smoke clears: quick, correct answers score the most. Five rounds, each faster and trickier than the last.", {"Watch the real ninja as his clones shuffle", "When they stop, move your marker and press A", "Quick, right picks score most (up to +5)", "Beware tricks! 5 rounds, the last is double"}, "dojo", 0xff8a1f, "mg/arena_clone-chaos.png", false},
  {"rooftop-glide", "Rooftop Glide", "Glide the night skyline and dodge the searchlights!", "Cape-glide over the rooftops of Hero Heights at night. Ride the warm air rising from the vents, swoop onto glowing clues and keep out of the sweeping searchlights: get spotted and you drop a clue for someone else to grab.", {"Hold A to glide on your cape, let go to dive", "Open the cape out of a dive to swoop up; vents lift you high", "Grab glowing clues: gold ones are worth 3", "Searchlights daze you and shake a clue loose! Most clues in 45 s wins"}, "heroes", 0x4a5fc1, "mg/arena_rooftop-glide.png", false},
  {"web-swing", "Web Swing", "Swing across the skyline to the finish tower!", "A race over the rooftops of Hero Heights at sunset. Web the glowing anchor points, swing, and let go on the upswing to fling yourself onward. Chain swing after swing; miss and you drop to the street and lose time.", {"Press A to web the nearest glowing anchor, hold to swing", "Let go as you swing up for a PERFECT fling", "Miss and you drop to the street, losing time", "First to the finish tower wins (or furthest after 50 s)"}, "heroes", 0xe0485a, "mg/arena_web-swing.png", false},
  {"repulsor-range", "Repulsor Range", "Blast the drones, spare the balloons!", "Hover over the Hero Heights test range at dusk and put your blasters to the test. Aim with the stick, tap A for quick blasts or charge a big one, pop drones and targets for points and keep a combo going. Never hit the passenger balloons!", {"Aim your reticle with the stick", "Tap A: quick blast. Hold A and let go: a big charged blast", "Pop drones and targets; keep hitting for a combo", "Hitting a balloon costs 3 points! Top score in 45 s wins"}, "heroes", 0xd9a02a, "mg/arena_repulsor-range.png", false},
  {"ring-rush", "Ring Rush", "Race the checkered hills and grab every ring!", "Four lanes of checkered hills rush past. Hop between lanes to scoop up rings, jump the wind-up crawler bots and spin-dash through the propeller bots. Get bonked and your rings go flying for anyone to grab!", {"Up / Down switches lanes: follow the rings", "A jumps crawler bots; X spin-dashes through any bot (and rivals!)", "A bot hit scatters your rings for anyone to grab", "Most rings after 45 seconds wins"}, "toons", 0x1e63d6, "mg/arena_ring-rush.png", false},
  {"patty-panic", "Patty Panic", "Order up! Stack them fast and stack them right!", "The undersea diner is packed! Each ticket shows a burger from the bottom bun up. Press each topping’s button in order to stack it, and serve it before the customer loses patience. One wrong button and the whole stack topples!", {"Each ticket shows a burger, bottom to top", "Press the toppings in order: X patty, A lettuce, B tomato, Y cheese", "A wrong button topples the stack: start again!", "Serve before the customer gives up: most orders in 50 seconds wins"}, "toons", 0xf2c418, "mg/arena_patty-panic.png", false},
  {"donut-dash", "Donut Dash", "Catch your colour, dodge the broccoli!", "Five conveyor belts roll fresh donuts out of the ovens and toss them across the factory floor. Catch the ones frosted in your colour, grab the rainbow ones before anyone else and keep clear of the broccoli and the burnt ones. The belts keep speeding up!", {"Catch donuts frosted in your colour (your shape shows on their landing ring)", "Rainbow donuts count double for anyone; broccoli and burnt ones cost a donut", "A dashes, and bumps rivals off a good spot", "The belts speed up: most donuts after 45 seconds wins"}, "toons", 0xff8fb1, "mg/arena_donut-dash.png", false},
  {"hip-shake", "Hip-Shake Hustle", "Rock the bandshell, right on the beat!", "A rock-and-roll dance-off on a 1950s bandshell. Moves fall down your spotlight in time with the band: hit them on the beat, chain streaks and make the crowd swoon.", {"Arrows fall to your shape: push the stick that way on the beat", "Stars are poses: press A on the beat", "PERFECT on the beat; 8 in a row raises your multiplier", "Top score wins; the final 10 seconds are an encore worth double"}, "showtime", 0xff4f8b, "mg/arena_hip-shake.png", false},
  {"coffee-rush", "Coffee Rush", "Pull the perfect shot, swirl the perfect heart!", "Behind the counter of a pastel café: pull espresso shots right to the line, pour latte art and serve every customer before they give up waiting. Perfect pours score more.", {"Hold A to pull a shot; let go on the gold fill line", "Then tap A as the milk swirl passes the pink heart", "Serve before the order ring runs out; perfect pours score more", "Most points wins; the last 10 seconds are rush hour, worth double"}, "showtime", 0xf7a1c4, "mg/arena_coffee-rush.png", false},
  {"rhinestone-rodeo", "Rhinestone Rodeo", "Hold on to your hat, partner!", "Ride a sparkly mechanical pony in a pink honky-tonk ring. Every buck is telegraphed: lean the right way to stay in the saddle. The bucks get wilder and wilder!", {"Before each buck your pony tips one way; an arrow shows which", "Lean that way with the stick before it bucks to stay on", "Thrown off? You lose 2 seconds and climb back on", "The bucks get wilder: longest time in the saddle wins"}, "showtime", 0xff5fa8, "mg/arena_rhinestone-rodeo.png", false},
  {"slapshot", "Slapshot Showdown", "Guard your goal, blast the puck!", "A four-sided ice rink under the Showtime lights: everyone guards the goal on their side. Grab the puck, wind up a slapshot and fire it into a rival goal — but every goal you let in costs you. A second puck drops in for the finale!", {"Skate into the puck to pick it up", "Hold A to wind up a slapshot, let go to fire", "Score in a rival goal for +2 — letting one in costs 1", "No puck? A checks. Last 10 s: a second puck!"}, "showtime", 0x3aa7e0, "mg/arena_slapshot.png", false},
  {"free-throw", "Free Throw Frenzy", "Shoot hoops on the garden court!", "Shoot hoops on a sunny garden court. Stop the power bar in the green, then the aim needle — swishes score a bonus, the golden ball of every rack doubles it, and in the final seconds the hoop starts to slide!", {"Press A to stop the power bar in the green", "Press A again to stop the aim needle in the green", "Basket 2, swish 3 — the golden ball doubles it", "Last 10 s: the hoop slides, every basket +1"}, "capitol", 0xee7a2f, "mg/arena_free-throw.png", false},
  {"fairway", "Fairway Frenzy", "Pitch and putt on the rolling green!", "Pitch and putt on a rolling green in the gardens. Aim, hold A to power up and let go — the tee shot rides the wind and the ball rolls with the slopes. Hole out in fewer strokes for more points; when time runs out on a hole, the ball closest to the pin scores too.", {"Stick aims, hold A to power up, let go to hit", "Wind pushes tee shots; the ball rolls downhill", "Hole out in 1 stroke for 5, in 2 for 3, in 3 for 2", "Closest to the pin scores 2 — last 10 s double"}, "capitol", 0x4caf50, "mg/arena_fairway.png", false},
};
